{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.INT_CHANNEL_SPEND AS SELECT LOWER(TRIM(channel)) AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.maplemonk_analytics_MARKETING_CONSOLIDATED` GROUP BY 1,2; CREATE OR REPLACE TABLE MAPLEMONK.INT_AMAZON_CHANNEL_SPEND AS SELECT \'amazon\' AS channel, DATE(date) AS date, SUM(spend) AS total_channel_spend FROM `maplemonk-analytics.maplemonk.fytika_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` GROUP BY 1,2; CREATE OR REPLACE TABLE MAPLEMONK.INT_FACEBOOK AS SELECT DATE(fc.Date) AS date, LOWER(fc.Channel) AS channel, LOWER(TRIM(CAST(fc.product_id AS STRING))) AS product_id, sku, product_name_final, product_Category, fc.Spend, fc.sales revenue FROM `maplemonk.fytika_db_Product_FACEBOOK_CONSOLIDATED` fc ; CREATE OR REPLACE TABLE MAPLEMONK.INT_GOOGLE AS SELECT gc.date, gc.Channel, product_id, SKU, product_name_final, product_category, spend, sales FROM `maplemonk.Fytika_db_Product_GOOGLEADS_CONSOLIDATED` gc ; CREATE OR REPLACE TABLE MAPLEMONK.INT_AMAZON AS SELECT DATE(a.Date) AS date, \'amazon\' AS channel, LOWER(TRIM(a.channel_Product_id)) AS product_id, pl.sku_code sku, pm.name product_name_final, pm.category_name product_category, sum(a.spend) spend, SUM(a.ATTRIBUTED_SALES_14D) AS revenue, FROM `maplemonk-analytics.maplemonk.fytika_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` a left join ( select distinct case when sku_code = \'\' then SPLIT(seller_sku_on_channel, \'-\')[OFFSET(0)] else sku_code end sku_code , channel_product_id from maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_listing where lower(channelname) like \'%amazon%\' qualify row_number() over (partition by channel_product_id order by date(updated) desc) = 1 ) pl on lower(pl.channel_product_id) = lower(REPLACE(a.asin, \'\"\', \'\')) left join ( select product_code, name, category_name, mrp from maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_master qualify row_number() over (partition by product_code order by date(updated) desc) = 1 ) pm on pm.product_code = pl.sku_code where a.ad_type_1 <> \'SPONSORED BRANDS\' GROUP BY 1,2,3,4,5,6; CREATE OR REPLACE TABLE MAPLEMONK.INT_FLIPKART AS SELECT DATE(fk.Date) AS date, LOWER(fk.Channel) AS channel, fk.product_id, sku, product_name_final, product_category, fk.Spend, fk.sales revenue FROM `maplemonk.Fytika_db_Product_Flipkart_FSN` fk ; CREATE OR REPLACE TABLE MAPLEMONK.INT_MARKETING_COMBINED AS SELECT * FROM MAPLEMONK.INT_FACEBOOK UNION ALL SELECT * FROM MAPLEMONK.INT_GOOGLE UNION ALL SELECT * FROM MAPLEMONK.INT_AMAZON UNION ALL SELECT * FROM MAPLEMONK.INT_FLIPKART; CREATE OR REPLACE TABLE MAPLEMONK.FYTIKA_DB_PRODUCT_MARKETING_CONSOLIDATED PARTITION BY date AS WITH base AS ( SELECT m.*, SUM(spend) OVER (PARTITION BY date, channel) AS total_spend, SUM(revenue) OVER (PARTITION BY date, channel) AS total_sales FROM MAPLEMONK.INT_MARKETING_COMBINED m ) SELECT b.*, COALESCE( CASE WHEN b.channel = \'amazon\' THEN ac.total_channel_spend ELSE cs.total_channel_spend END, 0 ) AS total_channel_spend, GREATEST( CASE WHEN b.total_sales != 0 THEN b.spend + ( IFNULL( CASE WHEN b.channel = \'amazon\' THEN ac.total_channel_spend ELSE cs.total_channel_spend END, b.total_spend ) - b.total_spend ) * (b.revenue / b.total_sales) ELSE b.spend END, 0 ) AS corrected_spend FROM base b LEFT JOIN MAPLEMONK.INT_CHANNEL_SPEND cs ON lower(b.channel) = lower(cs.channel) AND b.date = cs.date LEFT JOIN MAPLEMONK.INT_AMAZON_CHANNEL_SPEND ac ON lower(b.channel) = lower(ac.channel) AND b.date = ac.date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            